Deno.test("spider onSeen self-throw is cooldown-gated for 3 turns", () => {
  clearAll();
  const tiles = new Uint8Array(CHUNK_SIZE * CHUNK_SIZE).fill(TILE_FLOOR);
  loadChunk(0, 0, tiles);
  try {
    const world = new World({ seed: 1 });
    world.rand = () => 0.0;
    const thrown = [];
